function openDialog(title,body,actions='',wide=false){returnFocus=document.activeElement;const d=$('dialog');d.className=wide?'wide':'';d.innerHTML=`<header class="dialog-head"><h2 id="dialog-title">${title}</h2>${btn('Close','إغلاق','close','quiet',`aria-label="${t('Close dialog','إغلاق النافذة')}"`)}</header>${body}<div class="dialog-actions">${actions}</div>`;d.setAttribute('aria-labelledby','dialog-title');d.showModal();d.querySelector('input,textarea,button')?.focus();}
